{
  "name": "微型FPGA时序控制器",
  "name_en": "Micro FPGA Timing Controller",
  "manufacturer": "",
  "description": "这是一种基于FPGA的实验时序与触发控制器，通常通过USB连接，用于显微成像和光学实验中的相机、激光器及其他外设同步。它可提供激光触发控制、相机触发时序、TTL/PWM/舵机输出以及模拟量输入采集，适合需要精确微秒级同步的实验系统。",
  "description_en": "This is an FPGA-based laboratory timing and trigger controller, typically connected over USB, for synchronizing cameras, lasers, and other peripherals in microscopy and optical experiments. It provides laser trigger control, camera timing generation, TTL/PWM/servo outputs, and analog input readback, making it suitable for setups that require precise microsecond-level synchronization.",
  "tag_hints": [
    "FPGA timing control",
    "camera-laser synchronization",
    "microscopy triggering",
    "TTL I/O",
    "PWM output",
    "servo control",
    "analog input",
    "microsecond pulse sequencing"
  ],
  "actions": [
    {
      "action_name": "auto-is_connected",
      "description": "检查设备是否已连接。",
      "description_en": "Check whether the device is connected."
    },
    {
      "action_name": "auto-get_number_lasers",
      "description": "获取激光通道数量。",
      "description_en": "Get the number of laser channels."
    },
    {
      "action_name": "auto-get_number_ttls",
      "description": "获取TTL通道数量。",
      "description_en": "Get the number of TTL channels."
    },
    {
      "action_name": "auto-get_number_servos",
      "description": "获取舵机通道数量。",
      "description_en": "Get the number of servo channels."
    },
    {
      "action_name": "auto-get_number_pwms",
      "description": "获取PWM通道数量。",
      "description_en": "Get the number of PWM channels."
    },
    {
      "action_name": "auto-get_number_analogs",
      "description": "获取模拟输入通道数量。",
      "description_en": "Get the number of analog input channels."
    },
    {
      "action_name": "auto-set_ttl_state",
      "description": "设置指定TTL通道的状态。",
      "description_en": "Set the state of the specified TTL channel."
    },
    {
      "action_name": "auto-get_ttl_state",
      "description": "获取指定TTL通道的状态。",
      "description_en": "Get the state of the specified TTL channel."
    },
    {
      "action_name": "auto-set_servo_state",
      "description": "设置指定舵机通道的状态。",
      "description_en": "Set the state of the specified servo channel."
    },
    {
      "action_name": "auto-get_servo_state",
      "description": "获取指定舵机通道的状态。",
      "description_en": "Get the state of the specified servo channel."
    },
    {
      "action_name": "auto-set_pwm_state",
      "description": "设置指定PWM通道的状态。",
      "description_en": "Set the state of the specified PWM channel."
    },
    {
      "action_name": "auto-get_pwm_state",
      "description": "获取指定PWM通道的状态。",
      "description_en": "Get the state of the specified PWM channel."
    },
    {
      "action_name": "auto-get_analog_state",
      "description": "获取指定模拟输入通道的电压测量值。",
      "description_en": "Get the voltage reading of the specified analog input channel."
    },
    {
      "action_name": "auto-set_mode_state",
      "description": "设置指定激光通道的触发模式。",
      "description_en": "Set the trigger mode of the specified laser channel."
    },
    {
      "action_name": "auto-get_mode_state",
      "description": "获取指定激光通道的触发模式。",
      "description_en": "Get the trigger mode of the specified laser channel."
    },
    {
      "action_name": "auto-set_duration_us",
      "description": "设置指定激光通道的脉冲持续时间（微秒）。",
      "description_en": "Set the pulse duration of the specified laser channel in microseconds."
    },
    {
      "action_name": "auto-get_duration_us",
      "description": "获取指定激光通道的脉冲持续时间（微秒）。",
      "description_en": "Get the pulse duration of the specified laser channel in microseconds."
    },
    {
      "action_name": "auto-set_sequence_state",
      "description": "设置指定激光通道的触发序列。",
      "description_en": "Set the trigger sequence of the specified laser channel."
    },
    {
      "action_name": "auto-get_sequence_state",
      "description": "获取指定激光通道的触发序列。",
      "description_en": "Get the trigger sequence of the specified laser channel."
    },
    {
      "action_name": "auto-set_laser_state",
      "description": "设置指定激光通道的触发参数。",
      "description_en": "Set the trigger parameters of the specified laser channel."
    },
    {
      "action_name": "auto-get_laser_state",
      "description": "获取指定激光通道的触发参数。",
      "description_en": "Get the trigger parameters of the specified laser channel."
    },
    {
      "action_name": "auto-is_active_sync",
      "description": "检查设备是否处于主动同步模式。",
      "description_en": "Check whether the device is in active synchronization mode."
    },
    {
      "action_name": "auto-set_camera_pulse",
      "description": "设置相机触发脉冲宽度（微秒）。",
      "description_en": "Set the camera trigger pulse width in microseconds."
    },
    {
      "action_name": "auto-get_camera_pulse",
      "description": "获取相机触发脉冲宽度（微秒）。",
      "description_en": "Get the camera trigger pulse width in microseconds."
    },
    {
      "action_name": "auto-set_camera_readout",
      "description": "设置相机读出时间（微秒）。",
      "description_en": "Set the camera readout time in microseconds."
    },
    {
      "action_name": "auto-get_camera_readout",
      "description": "获取相机读出时间（微秒）。",
      "description_en": "Get the camera readout time in microseconds."
    },
    {
      "action_name": "auto-set_camera_exposure",
      "description": "设置相机曝光时间（微秒）。",
      "description_en": "Set the camera exposure time in microseconds."
    },
    {
      "action_name": "auto-get_camera_exposure",
      "description": "获取相机曝光时间（微秒）。",
      "description_en": "Get the camera exposure time in microseconds."
    },
    {
      "action_name": "auto-set_laser_delay",
      "description": "设置相机与激光触发之间的延迟（微秒）。",
      "description_en": "Set the delay between camera and laser triggering in microseconds."
    },
    {
      "action_name": "auto-get_laser_delay",
      "description": "获取相机与激光触发之间的延迟（微秒）。",
      "description_en": "Get the delay between camera and laser triggering in microseconds."
    },
    {
      "action_name": "auto-set_camera_state",
      "description": "设置相机触发模块参数（脉冲、延迟、曝光、读出），单位为微秒。",
      "description_en": "Set the camera trigger module parameters (pulse, delay, exposure, readout) in microseconds."
    },
    {
      "action_name": "auto-get_camera_state",
      "description": "获取相机触发模块参数，单位为微秒。",
      "description_en": "Get the camera trigger module parameters in microseconds."
    },
    {
      "action_name": "auto-set_camera_state_ms",
      "description": "设置相机触发模块参数（脉冲、延迟、曝光、读出），单位为毫秒。",
      "description_en": "Set the camera trigger module parameters (pulse, delay, exposure, readout) in milliseconds."
    },
    {
      "action_name": "auto-get_camera_state_ms",
      "description": "获取相机触发模块参数，单位为毫秒。",
      "description_en": "Get the camera trigger module parameters in milliseconds."
    },
    {
      "action_name": "auto-start_camera",
      "description": "启动相机触发与激光同步。",
      "description_en": "Start camera triggering and laser synchronization."
    },
    {
      "action_name": "auto-stop_camera",
      "description": "停止相机触发与激光同步。",
      "description_en": "Stop camera triggering and laser synchronization."
    },
    {
      "action_name": "auto-is_camera_running",
      "description": "检查相机触发是否正在运行。",
      "description_en": "Check whether camera triggering is currently running."
    },
    {
      "action_name": "auto-set_active_sync",
      "description": "设置为主动同步模式。",
      "description_en": "Set the device to active synchronization mode."
    },
    {
      "action_name": "auto-set_passive_sync",
      "description": "设置为被动同步模式。",
      "description_en": "Set the device to passive synchronization mode."
    },
    {
      "action_name": "auto-get_id",
      "description": "获取设备的人类可读标识符。",
      "description_en": "Get the human-readable device identifier."
    }
  ]
}

